# 関数を定義
def greet_by_time(name, hour):
    if hour < 12:
        return "おはよう、" + name + "さん!"
    elif hour < 18:
        return "こんにちは、" + name + "さん!"
    else:
        return "こんばんは、" + name + "さん!"

print(greet_by_time("太郎", 9))

